  const l = SP.lineasPropuestas(f, items, ficha).map(x => ({ ...x }));
  const llenas = l.filter(x => Math.round(Number(x.monto) || 0) > 0);
  if (!llenas.length) return [{ item: (l[0] && l[0].item) || '', area: (l[0] && l[0].area) || '', monto: Math.abs(Math.round(v.total)) }];
