  const l = l0.map((r, i) => ({ r, i })).sort((a, b) => ((b.r.pt ? b.r.pt.valor : -1) - (a.r.pt ? a.r.pt.valor : -1)) || a.i - b.i).map(x => x.r);
  const spIds = new Set(SP.candidatosCargo(c, D.siiPendientes || []).map(k => k.v.id));
  if (!l.length) return `<p class="ayuda bj-res-vacio">${q ? 'Nada en Gastos con eso (últimos 150 días).' : `Nada registrado en Gastos de ${pesos(c.monto)}. Escribe otro monto, el proveedor o el folio.`}</p>`;
  // v0.81.5 · El elegido se ve: borde y fondo verdes, "Elegido" con su marca
  const eleG = cart.modo[c.id] === 'gasto' ? cart.gasto[c.id] || '' : '';
  return `${q ? '' : `<p class="ayuda">Del mismo monto (${pesos(c.monto)}):</p>`}<div class="bj-cards">${l.map(r => {
    const yaEl = r.accion === 'gasto' && eleG && r.clave === eleG;
    const bt = r.accion === 'gasto' ? (yaEl ? `<span class="bj-elegido">${icono('check', 14)} Elegido: confírmalo abajo</span>` : `<button type="button" class="btn-sec btn-chico" data-bj-elegir="gasto" data-cc="${esc(c.id)}" data-k="${esc(r.clave)}" ${cart.ocupado ? 'disabled' : ''}>Es este gasto</button>`)
      : r.accion === 'venc' ? `<button type="button" class="btn-sec btn-chico" data-bj-elegir="venc" data-cc="${esc(c.id)}" data-k="${esc(r.id)}" ${cart.ocupado ? 'disabled' : ''}>Pagar con este cargo</button>`
      : r.accion === 'sii' ? (spIds.has(r.id) ? `<button type="button" class="btn-sec btn-chico" data-bj-elegir="sii" data-cc="${esc(c.id)}" data-k="${esc(r.id)}" ${cart.ocupado ? 'disabled' : ''}>Clasificar y conciliar</button>` : '<a class="btn-link btn-chico" href="#gastos/sii/porclasificar">Ir a Por clasificar</a>') : '';
    const o = r.cargoId ? ccPorId(r.cargoId) : null;
    return cardBj({ titulo: r.titulo, monto: r.monto, sub: r.sub, tono: r.estado.tono, estado: r.estado.texto, pt: r.pt, attrs: `data-bj-r="${esc(r.fuente)}"${yaEl ? ' data-bj-elegida aria-current="true"' : ''}`, extra: (bt ? `<div class="bj-card-bot">${bt}</div>` : '') + (o ? regCargoHtml(o) : '') });
  }).join('')}</div>`;
