const diasDesde = f => { const m = /^(\d{4})-(\d{2})-(\d{2})/.exec(f || ''); if (!m) return 0; return Math.round((new Date(Caja.diaLocal() + 'T12:00:00') - new Date(`${m[1]}-${m[2]}-${m[3]}T12:00:00`)) / 864e5); };
